// Локализация интерфейса.
//
// Ключом перевода служит русская строка из разметки: вызов t('Настройки')
// понятен прямо на месте, а незаполненная строка безопасно остаётся русской,
// а не превращается в пустое место или «ключ». Подстановка — через {name},
// склоняемые слова — через tp() с формами one/few/many.
import { useCallback } from 'react';
import { useStore } from '../store';
