  'Java для запуска Minecraft': 'Java to run Minecraft',
  'Лаунчер скачает Java сам, а уже установленную найдёт автоматически.': 'The launcher can download Java itself and will detect the one you already have.',
  'Java пока не найдена — скачайте её ниже.': 'No Java found yet — download it below.',
