  'Защита от модов': 'Mod protection',
  'Минимальная': 'Minimal',
  'Стандартная': 'Standard',
  'Жёсткая': 'Strict',
  'Моды работают внутри игры, поэтому полной изоляции не бывает. Чем выше уровень, тем меньше мод может сделать в системе.': 'Mods run inside the game, so complete isolation is impossible. The higher the level, the less a mod can do in the system.',
  'Стандартная: запрет на буфер обмена, чужие окна и настройки экрана. Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение.': 'Standard: no clipboard, no other windows, no display settings. Strict: also low integrity — writing only to the profile folder, everything else read-only.',
  'Не гарантирует работу всех модов.': 'Does not guarantee that every mod will work.',
  'Изолировать': 'Isolate',
  'Изолирован': 'Isolated',
