  'Описание': 'Description',
  'Описание недоступно': 'Description is unavailable',
  'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Minimal: the game closes together with the launcher. Standard: also no clipboard, no other windows, no display settings.',
  'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена.': 'Minimal: the game closes together with the launcher. Standard: also no clipboard.',
  'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': 'Strict: also low integrity — writing only to the profile folder, everything else read-only. Does not guarantee that every mod will work.',
  'Игра запускается в песочнице: мод не может писать за пределами папки профиля. На стандартном и жёстком уровнях он ещё и не может запускать другие программы. Буфер обмена не ограничивается.': 'The game runs in a sandbox: a mod cannot write outside the profile folder. On standard and strict levels it also cannot launch other programs. The clipboard is not restricted.',
  'Минимальная: игра в песочнице — не может писать за пределами папки профиля. Стандартная: ещё и не может запускать другие программы.': 'Minimal: the game runs in a sandbox — it cannot write outside the profile folder. Standard: it also cannot launch other programs.',
  'Жёсткая: то же плюс отдельные HOME/APPDATA/TEMP внутри профиля.': 'Strict: the same plus separate HOME/APPDATA/TEMP inside the profile.',
  'Игра закрылась с ошибкой': 'The game crashed',
  'Код выхода: {code}. Подробности — в crash-логе игры.': 'Exit code: {code}. See the game crash log for details.',
  'Открыть папку игры': 'Open game folder',
  'Понятно': 'Got it',
  'Вход через LittleSkin': 'Sign in with LittleSkin',
  'Аккаунт LittleSkin — логин и пароль.': 'LittleSkin account — login and password.',
  'Удалить аккаунт?': 'Delete account?',
  'Аккаунт {name} будет удалён с этого компьютера.': 'Account {name} will be removed from this computer.',
  'Включить анимации': 'Enable animations',
  'Ускоритель лаунчера': 'Launcher accelerator',
  'Если сборки медленно скачиваются, включите эту функцию.': 'If modpacks download slowly, enable this function.',
  'Разбивает первый TLS-пакет на части, чтобы DPI не прочитал домен. Помогает, если не открываются Modrinth, CurseForge, GitHub или не качаются версии. Может не работать у некоторых провайдеров.': 'Splits the first TLS packet so DPI cannot read the domain. Helps when Modrinth, CurseForge, GitHub or version downloads do not load. May not work with some ISPs.',
