  'Кнопка «ИИ-сборка» в «Установках»: ассистент подбирает моды, ресурс-паки и шейдеры по описанию и сам скачивает их в новый профиль.': 'The "AI modpack" button in Installations: the assistant picks mods, resource packs and shaders from your description and downloads them into a new profile.',
