  'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': 'Leave the limit empty and the pack gets as many mods as it needs. "Both at once" searches both catalogs; a preferred one is searched first, then the other if nothing is found.',
  'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник: «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': 'Limit: the maximum number of mods to pick — leave it empty for "as many as the pack needs". Source: "Both at once" searches both catalogs; a preferred one is searched first, then the other if nothing is found.',
  'Скрывать лаунчер при запуске игры': 'Hide launcher on game launch',
  'Dracula': 'Dracula',
  'Alucard': 'Alucard',
  'Dracula использует официальную палитру Dracula (тёмная) и Alucard (светлая) — выбранный цвет на неё не влияет.': 'Dracula uses the official Dracula (dark) and Alucard (light) palettes — the selected color does not affect it.',
  'Дубликаты, версии модов, память, зависимости и Java': 'Duplicates, mod versions, memory, dependencies and Java',
  'Столько ОЗУ система не отдаст: оставьте ей хотя бы 1 ГБ, иначе игра вылетит при запуске.': 'The system will not give that much RAM: leave it at least 1 GB or the game will crash on launch.',
  'Для сборок с модами меньше 2 ГБ почти всегда мало — начнутся лаги и вылеты.': 'For modded packs under 2 GB is almost always too little — expect stutters and crashes.',
  '.mrpack — формат Modrinth: моды скачиваются по ссылкам, конфиги внутри архива. .zip — формат CurseForge (manifest.json + overrides), его понимают CurseForge и Prism.': '.mrpack — the Modrinth format: mods are downloaded by URL, configs are inside. .zip — the CurseForge format (manifest.json + overrides), understood by CurseForge and Prism.',
  '.mrpack — формат Modrinth: моды скачиваются по ссылкам, конфиги внутри архива. .zip — формат CurseForge (manifest.json + overrides). MultiMC/Prism .zip — instance.cfg, mmc-pack.json и папка .minecraft, такой архив импортируется в Prism и MultiMC.': '.mrpack — the Modrinth format: mods are downloaded by URL, configs are inside. .zip — the CurseForge format (manifest.json + overrides). The MultiMC/Prism .zip has instance.cfg, mmc-pack.json and a .minecraft folder, and imports into Prism and MultiMC.',
