  'Вернуть папку профиля': 'Use profile folder',
  'Моды, миры, скриншоты и конфиги хранятся в этой папке. Подойдёт и существующий .minecraft — его содержимое останется на месте.': 'Mods, worlds, screenshots and configs live in this folder. An existing .minecraft works too — its contents stay where they are.',
