  'Прятать в трей при закрытии': 'Hide to tray when closed',
  'Закрытие окна не выключает лаунчер: он остаётся в трее. Выход — через меню иконки в трее.': 'Closing the window keeps the launcher in the tray. To quit, use the tray icon menu.',
