  'Скопируйте вручную.': 'Copy it manually.',
  'Co-op': 'Co-op',
  'Играйте с друзьями без своего сервера: один создаёт код, другой подключается по нему.': 'Play with friends without your own server: one creates a code, the other joins with it.',
  'Комнату можно создать заранее: отправьте код друзьям, потом запустите игру и откройте мир для сети — остальное лаунчер сделает сам.': 'You can create the room in advance: send the code to your friends, then start the game and open the world to LAN — the launcher does the rest.',
  'Сначала создайте профиль.': 'Create a profile first.',
  'Модель ИИ': 'AI model',
  'Первая доступная': 'First available',
  'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник и модель выбираются в окне «ИИ-сборка».': 'Limit: the maximum number of mods to pick — leave it empty for "as many as the pack needs". Source and model are chosen in the AI pack window.',
  'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом. Модель — кто именно собирает сборку.': 'Leave the limit empty and the pack gets as many mods as it needs. "Both at once" searches both catalogs; a preferred one is searched first, then the other. The model is who actually builds the pack.',
  'URL списка серверов': 'Server list URL',
  'Статичный JSON с серверами для раздела «Серверы». Формат описан в README проекта.': 'Static JSON with servers for the “Servers” section. The format is described in the project\'s README.',
  'Сканер модов': 'Mod scanner',
  'Перед запуском моды проверяются на подозрительные признаки: отправка данных на сторонние серверы, запуск процессов, обфускация и другое. Отчёт — во вкладке «Безопасность» профиля.': 'Before launching, mods are checked for suspicious signs: sending data to third-party servers, running processes, obfuscation, and more. The report is in the “Security” tab of the profile.',
  'Обычный: блокировка только при опасных признаках, подозрительные — на ваше усмотрение. Хеш мода с Modrinth заметно снижает оценку.': 'Normal: blocks only on dangerous signs; suspicious signs are up to you. A Modrinth hash noticeably lowers the score.',
  'Усиленный: блокировка и при некоторых одиночных признаках (нативные библиотеки, обфускация, java-агент), проверяются также конфиги и паки.': 'Strict: also blocks on some single signs (native libraries, obfuscation, java agent); configs and packs are checked too.',
  'Параноидальный: запускаются только моды с известным хешем и без признаков; заблокированные переносятся в карантин.': 'Paranoid: only mods with a known hash and no signs are allowed; blocked ones go to quarantine.',
  'ИИ-заметки сканера': 'AI Scanner Notes',
  'Внимание: для подозрительных модов найденные фрагменты кода (строки, имена классов) отправляются на сторонний ИИ-сервис, чтобы получить пояснение. Заметка не влияет на оценку сканера.': 'Attention: for suspicious mods, found code fragments (lines, class names) are sent to a third-party AI service to receive an explanation. The note does not affect the scanner\'s rating.',
  'Настройки лаунчера': 'Launcher settings',
  'Бенчмарк измеряет то, что видно из лаунчера: время загрузки игры (до готовности меню или мира) и потребление RAM/CPU процесса за сессию.': 'The benchmark measures what the launcher can see: game load time (until the menu or world is ready) and the process RAM/CPU usage for the session.',
  'FPS не измеряется — из процесса игры его не достать; для этого нужен вспомогательный мод внутри игры.': 'FPS is not measured — the game process does not expose it; that would require a helper mod inside the game.',
