  'Моды работают внутри игры, поэтому полной изоляции не бывает. Чем выше уровень, тем меньше мод может сделать в системе.': 'Моды работаютъ внутри игры, поэтому полной изолйации не бываетъ. Чемъ выше уровень, темъ меньше модъ можетъ сделать в системе.',
  'Стандартная: запрет на буфер обмена, чужие окна и настройки экрана. Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение.': 'Стандартнайа: запретъ на буферъ обмена, чужые окна и настройке экрана. Жёсткайа: исчо и низкайа целостность — писать можно только в папку профилйа, остальное только чтение.',
