  'Описание недоступно': 'Описание недоступно',
  'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена, чужие окна и настройки экрана.': 'Минимальнайа: игра закрываецца вместе с лаунчеромъ. Стандартнайа: исчо и запретъ на буферъ обмена, чужые окна и настройке экрана.',
  'Минимальная: игра закрывается вместе с лаунчером. Стандартная: ещё и запрет на буфер обмена.': 'Минимальнайа: игра закрываецца вместе с лаунчеромъ. Стандартнайа: исчо и запретъ на буферъ обмена.',
  'Жёсткая: ещё и низкая целостность — писать можно только в папку профиля, остальное только чтение. Не гарантирует работу всех модов.': 'Жёсткайа: исчо и низкайа целостность — писать можно только в папку профилйа, остальное только чтение. Не гарантируетъ работу всехъ модовъ.',
  'Игра запускается в песочнице: мод не может писать за пределами папки профиля. На стандартном и жёстком уровнях он ещё и не может запускать другие программы. Буфер обмена не ограничивается.': 'Игра запускаецца в песошнице: модъ не можетъ писать за пределами папки профилйа. На стандартномъ и жёсткомъ уровнйахъ он исчо и не можетъ запускать другие программы. Буферъ обмена не ограничиваецца.',
  'Минимальная: игра в песочнице — не может писать за пределами папки профиля. Стандартная: ещё и не может запускать другие программы.': 'Минимальнайа: игра в песошнице — не можетъ писать за пределами папки профилйа. Стандартнайа: исчо и не можетъ запускать другие программы.',
  'Жёсткая: то же плюс отдельные HOME/APPDATA/TEMP внутри профиля.': 'Жёсткайа: то же плюсъ отдельные HOME/APPDATA/TEMP внутри профилйа.',
  'Игра закрылась с ошибкой': 'Игра закрылась с ошыбкой',
  'Код выхода: {code}. Подробности — в crash-логе игры.': 'Кодъ выхода: {code}. Подробности — в crash-логе игры.',
