  'Разбивает первый TLS-пакет на части, чтобы DPI не прочитал домен. Помогает, если не открываются Modrinth, CurseForge, GitHub или не качаются версии. Может не работать у некоторых провайдеров.': 'Разбиваетъ первый TLS-пакетъ на части, чтобы DPI не прочиталъ доменъ. Помогаетъ, если не открываюцца Modrinth, CurseForge, GitHub или не качаюцца версии. Можетъ не работать у некоторыхъ провайдеровъ.',
