  'Виноват мод': 'Виноватъ модъ',
  'Лаунчер не нашёл ни crash-отчёта, ни логов: игра упала до их создания.': 'Лаунчеръ не нашёлъ ни crash-отчёта, ни логовъ: игра упала до их созданийа.',
  'latest.log заканчивается нормальным выходом игры, стека ошибки нет. Скорее всего, это лог прошлого запуска, а текущее падение не успело в него записаться.': 'latest.log заканчиваецца нормальнымъ выходомъ игры, стека ошыбки ниту. Скорее всиво, это логъ прошлово запуска, а текущее падение не успело в ниво записацца.',
  'Игре не хватило выделенной памяти — JVM была убита с OutOfMemoryError.': 'Игре не хватило выделенной памйати — JVM была убита с OutOfMemoryError.',
  'JVM упала на нативном вызове: {frame}': 'JVM упала на нативномъ вызове: {frame}',
  'Процесс Java завершился аварийно (не обычное исключение).': 'Процессъ Java завершылсйа аварийно (не обышное исключение).',
  'JVM упала в драйвере видеокарты: {frame}': 'JVM упала в драйвере видеокарты: {frame}',
  'JVM упала в нативном коде драйвера видеокарты.': 'JVM упала в нативномъ коде драйвера видеокарты.',
  'Мод или загрузчик собраны под другую версию Java. Игра не смогла загрузить классы.': 'Модъ или загрузчикъ собраны подъ другую версию Java. Игра не смогла загрузить классы.',
  'Мод или загрузчик собраны под другую версию Java. {error}': 'Модъ или загрузчикъ собраны подъ другую версию Java. {error}',
  'Игра не смогла создать окно/контекст OpenGL.': 'Игра не смогла создать окно/контекстъ OpenGL.',
  'Набор модов несовместим: чего-то не хватает или версии не совпадают.': 'Наборъ модовъ несовместимъ: чиво-то не хватаетъ или версии не совпадаютъ.',
  'Проблема с модами: {mods}.': 'Проблема с модами: {mods}.',
