  'Mixin-патч не применился: мод несовместим с этой версией игры или другого мода.': 'Mixin-патчъ не применилсйа: модъ несовместимъ с этой версией игры или другово мода.',
  'Отчёт прямо указывает на мод.': 'Отчётъ прйамо указываетъ на модъ.',
  'Отчёт прямо указывает на мод. {error}': 'Отчётъ прйамо указываетъ на модъ. {error}',
  'Судя по стеку, ошибка пришла из {mod}.': 'Судйа по стеку, ашыпка пришла из {mod}.',
  '{error}\n\nСудя по стеку, ошибка пришла из {mod}.': '{error}\n\nСудйа по стеку, ашыпка пришла из {mod}.',
  'Точную причину определить не удалось — смотрите лог.': 'Тошную причину определить не удалось — смотрите логъ.',
  '{error}\n\nТочную причину определить не удалось — смотрите лог.': '{error}\n\nТошную причину определить не удалось — смотрите логъ.',
  'Откройте папку игры и проверьте каталог crash-reports вручную.': 'Откройте папку игры и проверьте каталогъ crash-reports врушную.',
  'Запустите игру ещё раз — при новом падении отчёт появится здесь.': 'Запустите игру исчо разъ — при новомъ падении отчётъ пойавицца здесь.',
  'Посмотрите консоль лаунчера — ошибка могла остаться только в stderr.': 'Посмотрите консоль лаунчера — ашыпка могла остацца только в stderr.',
  'Запустите игру снова: при новом падении появится crash-report.': 'Запустите игру снова: при новомъ падении пойавицца crash-report.',
  'Откройте профиль → «Java и память» и поднимите верхний предел (например, 6144 МБ).': 'Откройте прохиль → «Java и памйать» и поднимите верхний пределъ (напримеръ, 6144 МБ).',
  'Не ставьте больше ~70% всей оперативной памяти — станет только хуже.': 'Не ставьте больше ~70% всей оперативной памйати — станетъ только хуже.',
  'Проверьте, нет ли рядом тяжёлых сборок с сотнями модов.': 'Проверьте, ниту ли рйадомъ тйажёлыхъ сбаракъ с сотнйами модовъ.',
  'Чаще всего это драйвер видеокарты или мод с нативным кодом (шейдеры, рендер).': 'Чаще всиво это драйверъ видеокарты или модъ с нативнымъ кодомъ (шейдеры, рендеръ).',
  'Обновите драйвер видеокарты.': 'Обновите драйверъ видеокарты.',
  'Уберите недавно добавленные моды и запустите снова.': 'Уберите недавно добавленные моды и запустите снова.',
  'Откройте профиль → «Java и память» и выберите версию: 1.16 и ниже — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.': 'Откройте прохиль → «Java и памйать» и выберите версию: 1.16 и ниже — Java 8, 1.17–1.20.4 — Java 17, 1.20.5+ — Java 21.',
  'Если Java нужной версии нет — скачайте её в настройках лаунчера.': 'Если Java нужной версии ниту — скачайте её в настройкахъ лаунчера.',
  'Обновите драйвер видеокарты (NVIDIA/AMD/Intel).': 'Обновите драйверъ видеокарты (NVIDIA/AMD/Intel).',
  'Проверьте, что видеокарта не отключена и игра не запущена в режиме удалённого рабочего стола.': 'Проверьте, што видеокарта не отключена и игра не запущена в режыме удалённово рабочиво стола.',
  'Уберите моды рендера/шейдеров, если падение началось после их установки.': 'Уберите моды рендера/шейдеровъ, если падение началось после их установки.',
  'Прочитайте строки «requires … which is missing» в отчёте — там перечислено, чего не хватает.': 'Прочитайте строки «requires … which is missing» в отчёте — тамъ перечислено, чиво не хватаетъ.',
  'Установите недостающие моды или уберите лишние.': 'Установите недостающие моды или уберите лишние.',
  'Проверьте, что все моды одной версии Minecraft.': 'Проверьте, што все моды одной версии Minecraft.',
  'Обновите виновный мод до версии под ваш Minecraft.': 'Обновите виновный модъ до версии подъ вашъ Minecraft.',
  'Уберите конфликтующий мод или его версию для другой сборки.': 'Уберите конфликтующий модъ или иво версию длйа другой сборки.',
  'Обновите или удалите виновный мод.': 'Обновите или удалите виновный модъ.',
  'Проверьте, что его версия совпадает с версией Minecraft.': 'Проверьте, што иво версыйа совпадаетъ с версией Minecraft.',
  'Обновите виновный мод или удалите его и проверьте запуск.': 'Обновите виновный модъ или удалите иво и проверьте запускъ.',
  'Если не помогло — отключите моды по половине, чтобы найти конфликт.': 'Если не помогло — отключите моды по палавине, чтобы найти конфликтъ.',
  'Откройте отчёт и посмотрите блок «Caused by» — там обычно указан мод.': 'Откройте отчётъ и посмотрите блокъ «Caused by» — тамъ обышно указанъ модъ.',
  'Отключите половину модов и запустите: так конфликт находится быстрее всего.': 'Отключите палавину модовъ и запустите: такъ конфликтъ находицца быстрее всиво.',
