  'Сначала Modrinth': 'Сначала Modrinth',
  'Сначала CurseForge': 'Сначала CurseForge',
  'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': 'Пусто в лимите — модовъ будетъ сколько нужно сборке. «Оба сразу» ищетъ в двухъ каталогахъ, приоритетный — сначала в нёмъ, а если тамъ пусто, то в другомъ.',
  'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник: «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом.': 'Лимитъ: сколько модовъ максимумъ подбирать — пусто значитъ «сколько нужно сборке». Истошникъ: «Оба сразу» ищетъ в двухъ каталогахъ, приоритетный — сначала в нёмъ, а если тамъ пусто, то в другомъ.',
  'Скрывать лаунчер при запуске игры': 'Скрывать лаунчеръ при запуске игры',
  'Дубликаты, версии модов, память, зависимости и Java': 'Дубликаты, версии модовъ, памйать, зависимости и Java',
  'Столько ОЗУ система не отдаст: оставьте ей хотя бы 1 ГБ, иначе игра вылетит при запуске.': 'Столько ОЗУ система не отдастъ: оставьте ей хотйа бы 1 ГБ, иначе игра вылетитъ при запуске.',
  'Для сборок с модами меньше 2 ГБ почти всегда мало — начнутся лаги и вылеты.': 'Длйа сбаракъ с модами меньше 2 ГБ почти всегда мало — нашнуцца лаги и вылеты.',
  '.mrpack — формат Modrinth: моды скачиваются по ссылкам, конфиги внутри архива. .zip — формат CurseForge (manifest.json + overrides), его понимают CurseForge и Prism.': '.mrpack — форматъ Modrinth: моды скачиваюцца по ссылкамъ, конфиги внутри архива. .zip — форматъ CurseForge (manifest.json + overrides), иво понимаютъ CurseForge и Prism.',
  '.mrpack — формат Modrinth: моды скачиваются по ссылкам, конфиги внутри архива. .zip — формат CurseForge (manifest.json + overrides). MultiMC/Prism .zip — instance.cfg, mmc-pack.json и папка .minecraft, такой архив импортируется в Prism и MultiMC.': '.mrpack — форматъ Modrinth: моды скачиваюцца по ссылкамъ, конфиги внутри архива. .zip — форматъ CurseForge (manifest.json + overrides). MultiMC/Prism .zip — instance.cfg, mmc-pack.json и папка .minecraft, такой архивъ импортируецца в Prism и MultiMC.',
