  'Через роутер (UPnP)': 'Черезъ роутеръ (UPnP)',
  'Скопируйте вручную.': 'Скопируйте врушную.',
  'Co-op': 'Co-op',
  'Играйте с друзьями без своего сервера: один создаёт код, другой подключается по нему.': 'Играйте с друзьйами безъ своиво сервера: одинъ создаётъ кодъ, другой подключаецца по нему.',
  'Комнату можно создать заранее: отправьте код друзьям, потом запустите игру и откройте мир для сети — остальное лаунчер сделает сам.': 'Комнату можно создать заранее: отправьте кодъ друзьйамъ, потомъ запустите игру и откройте миръ длйа сети — остальное лаунчеръ сделаетъ самъ.',
  'Сначала создайте профиль.': 'Сначала создайте прохиль.',
  'Модель ИИ': 'Модель ИИ',
  'Первая доступная': 'Первайа доступнайа',
  'Лимит: сколько модов максимум подбирать — пусто значит «сколько нужно сборке». Источник и модель выбираются в окне «ИИ-сборка».': 'Лимитъ: сколько модовъ максимумъ подбирать — пусто значитъ «сколько нужно сборке». Истошникъ и модель выбираюцца в окне «ИИ-сборка».',
  'Пусто в лимите — модов будет сколько нужно сборке. «Оба сразу» ищет в двух каталогах, приоритетный — сначала в нём, а если там пусто, то в другом. Модель — кто именно собирает сборку.': 'Пусто в лимите — модовъ будетъ сколько нужно сборке. «Оба сразу» ищетъ в двухъ каталогахъ, приоритетный — сначала в нёмъ, а если тамъ пусто, то в другомъ. Модель — кто именно собираетъ сборку.',
  'URL списка серверов': 'URL списка серверовъ',
  'Статичный JSON с серверами для раздела «Серверы». Формат описан в README проекта.': 'Статишный JSON с серверами длйа раздела «Серверы». Форматъ описанъ в README проекта.',
  'Сканер модов': 'Сканеръ модовъ',
  'Перед запуском моды проверяются на подозрительные признаки: отправка данных на сторонние серверы, запуск процессов, обфускация и другое. Отчёт — во вкладке «Безопасность» профиля.': 'Передъ запускомъ моды проверйаюцца на подозрительные признаки: отправка данныхъ на старанние серверы, запускъ процессовъ, обфускацийа и другое. Отчётъ — во вкладке «Безопасность» профилйа.',
  'Обычный: блокировка только при опасных признаках, подозрительные — на ваше усмотрение. Хеш мода с Modrinth заметно снижает оценку.': 'Обышный: блокировка только при опасныхъ признакахъ, подозрительные — на ваше усмотрение. Хешъ мода с Modrinth заметно снижаетъ оценку.',
  'Усиленный: блокировка и при некоторых одиночных признаках (нативные библиотеки, обфускация, java-агент), проверяются также конфиги и паки.': 'Усиленный: блокировка и при некоторыхъ одиношныхъ признакахъ (нативные библиотеки, обфускацийа, java-агентъ), проверйаюцца также конфиги и паки.',
  'Параноидальный: запускаются только моды с известным хешем и без признаков; заблокированные переносятся в карантин.': 'Параноидальный: запускаюцца только моды с известнымъ хешемъ и безъ признаковъ; заблокированные переносйацца в карантинъ.',
  'ИИ-заметки сканера': 'ИИ-заметки сканера',
  'Внимание: для подозрительных модов найденные фрагменты кода (строки, имена классов) отправляются на сторонний ИИ-сервис, чтобы получить пояснение. Заметка не влияет на оценку сканера.': 'Внимание: длйа подозрительныхъ модовъ найденные фрагменты кода (строки, имена классовъ) отправлйаюцца на старанний ИИ-сервисъ, чтобы получить пойаснение. Заметка не влийаетъ на оценку сканера.',
  'Настройки лаунчера': 'Настройке лаунчера',
  'Бенчмарк измеряет то, что видно из лаунчера: время загрузки игры (до готовности меню или мира) и потребление RAM/CPU процесса за сессию.': 'Бенчмаркъ измерйаетъ то, што видно из лаунчера: времйа загрузки игры (до готовности меню или мира) и потребление RAM/CPU процесса за сессию.',
  'FPS не измеряется — из процесса игры его не достать; для этого нужен вспомогательный мод внутри игры.': 'FPS не измерйаецца — из процесса игры иво не достать; длйа этово нуженъ вспомогательный модъ внутри игры.',
